//! Non-interactive UI for CI/headless environments.

use crate::error::{BivvyError, Result};

use super::theme::BivvyTheme;
use super::{
    OutputMode, OutputWriter, ProgressDisplay, Prompt, PromptResult, PromptType, Prompter,
    SpinnerFactory, SpinnerHandle, UiState,
};

/// UI implementation for non-interactive mode.
///
/// Used by every command (init, status, list, run, …) when running
/// without a TTY. Run-path workflow chrome lives in
/// [`crate::runner::display::NonInteractiveWorkflowDisplay`] — this
/// type only handles generic [`UserInterface`] traits.
pub struct NonInteractiveUI {
    mode: OutputMode,
    #[allow(dead_code)]
    is_ci: bool,
}

impl NonInteractiveUI {
    /// Create a new non-interactive UI.
    pub fn new(mode: OutputMode) -> Self {
        Self {
            mode,
            is_ci: crate::shell::is_ci(),
        }
    }

    /// Create with explicit CI flag (for testing).
    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
        Self { mode, is_ci }
    }
}

impl OutputWriter for NonInteractiveUI {
    fn message(&mut self, msg: &str) {
        if self.mode.shows_status() {
            println!("{}", msg);
        }
    }

    fn success(&mut self, msg: &str) {
        if self.mode.shows_status() {
            println!("✓ {}", msg);
        }
    }

    fn warning(&mut self, msg: &str) {
        if self.mode.shows_status() {
            eprintln!("⚠ {}", msg);
        }
    }

    fn error(&mut self, msg: &str) {
        eprintln!("✗ {}", msg);
    }

    fn show_hint(&mut self, hint: &str) {
        if self.mode.shows_status() {
            println!("  💡 {}", hint);
        }
    }

    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
        let pad = " ".repeat(indent);
        eprintln!();
        eprintln!("{}┌─ Command ──────────────────────────", pad);
        eprintln!("{}│ {}", pad, command);
        if !output.is_empty() {
            eprintln!("{}├─ Output ───────────────────────────", pad);
            for line in output.lines() {
                eprintln!("{}│ {}", pad, line);
            }
        }
        eprintln!("{}└────────────────────────────────────", pad);
        if let Some(h) = hint {
            eprintln!();
            eprintln!("{}Hint: {}", pad, h);
        }
    }
}

impl Prompter for NonInteractiveUI {
    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });

        // Check environment override (KEY=value, e.g. BUMP=minor).
        // This is handled by prompt_user for TerminalUI, but
        // NonInteractiveUI doesn't call prompt_user, so check here too.
        if let Some(result) = super::prompts::env_override(prompt) {
            return Ok(result);
        }

        // Use default
        if let Some(default) = &prompt.default {
            if is_multiselect {
                let values: Vec<String> =

content.content:
100	                let values: Vec<String> =
101	                    default.split(',').map(|s| s.trim().to_string()).collect();
102	                return Ok(PromptResult::Strings(values));
103	            }
104	            return Ok(PromptResult::String(default.clone()));
105	        }
106	
107	        Err(BivvyError::ConfigValidationError {
108	            message: format!(
109	                "Cannot prompt for '{}' in non-interactive mode (no default value)",
110	                prompt.key
111	            ),
112	        })
113	    }
114	}
115	
116	impl SpinnerFactory for NonInteractiveUI {
117	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
118	        if self.mode.shows_spinners() {
119	            println!("  {}", message);
120	        }
121	        Box::new(NoopSpinner { indent: 0 })
122	    }
123	
124	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
125	        if self.mode.shows_spinners() {
126	            let prefix = " ".repeat(indent);
127	            println!("{}{}", prefix, message);
128	        }
129	        Box::new(NoopSpinner { indent })
130	    }
131	}
132	
133	impl ProgressDisplay for NonInteractiveUI {
134	    fn show_header(&mut self, title: &str) {
135	        if self.mode.shows_status() {
136	            println!("\n{}\n", title);
137	        }
138	    }
139	
140	    fn show_progress(&mut self, current: usize, total: usize) {
141	        if self.mode.shows_status() {
142	            println!("[{}/{}]", current, total);
143	        }
144	    }
145	}
146	
147	impl UiState for NonInteractiveUI {
148	    fn output_mode(&self) -> OutputMode {
149	        self.mode
150	    }
151	
152	    fn is_interactive(&self) -> bool {
153	        false
154	    }
155	
156	    fn set_output_mode(&mut self, mode: OutputMode) {
157	        self.mode = mode;
158	    }
159	}
160	
161	/// Spinner that does nothing (for non-interactive mode).
162	struct NoopSpinner {
163	    indent: usize,
164	}
165	
166	impl SpinnerHandle for NoopSpinner {
167	    fn set_message(&mut self, _msg: &str) {}
168	
169	    fn finish_success(&mut self, msg: &str) {
170	        let prefix = " ".repeat(self.indent);
171	        let theme = BivvyTheme::new();
172	        println!("{}{}", prefix, theme.format_success(msg));
173	    }
174	
