impl<'a> Confirm<'a> {
    /// Creates a confirm prompt with a specific theme.
    ///
    /// ## Example
    ///
    /// ```rust,no_run
    /// use dialoguer::{theme::ColorfulTheme, Confirm};
    ///
    /// fn main() {
    ///     let confirmation = Confirm::with_theme(&ColorfulTheme::default())
    ///         .interact()
    ///         .unwrap();
